-- Check: topics, words and exercises this seed now has.
select
  (select count(*) from public.topics where slug in ('at-the-doctor', 'sports-fitness', 'celebrations', 'housing-renting', 'eating-out', 'personality', 'arts-culture', 'careers', 'society-issues', 'medicine-healthcare', 'attitudes-opinions')) as topics,
  (select count(*) from public.vocabulary_items v join public.topics t on t.id = v.topic_id where t.slug in ('at-the-doctor', 'sports-fitness', 'celebrations', 'housing-renting', 'eating-out', 'personality', 'arts-culture', 'careers', 'society-issues', 'medicine-healthcare', 'attitudes-opinions')) as words,
  (select count(*) from public.exercises e join public.topics t on t.id = e.topic_id where t.slug in ('at-the-doctor', 'sports-fitness', 'celebrations', 'housing-renting', 'eating-out', 'personality', 'arts-culture', 'careers', 'society-issues', 'medicine-healthcare', 'attitudes-opinions')) as exercises;
